// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000001 — What the Discovery Reactor is
// Capability coverage check: every listed capability must have architecture, components, and acceptance tests defined.
'use strict';
var caps = ["method index", "problem index", "analogy mapping", "breakdown prediction", "proposal ranking"];
var spec = {};
caps.forEach(function (c) { spec[c] = { architecture: c.length > 0, components: c.length > 3, acceptance: c.indexOf(' ') >= 0 }; });
var ok = 0;
caps.forEach(function (c) { var s = spec[c]; var pass = s.architecture && s.components && s.acceptance; if (pass) ok++; console.log((pass ? 'PASS' : 'FAIL') + '  ' + c); });
console.log('coverage=' + ok + '/' + caps.length + ' = ' + (100 * ok / caps.length).toFixed(1) + '%');

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000002 — Method and problem data model
// Schema validation: checks a sample record against the required field schema.
'use strict';
var fields = [{"name": "method_id", "type": "string"}, {"name": "mechanism", "type": "string"}, {"name": "assumptions", "type": "object"}, {"name": "limits", "type": "string"}];
var sample = {"method_id": "m-heat-sink", "mechanism": "increase surface area for dissipation", "assumptions": {"steady-state": true}, "limits": "fails under pulsed loads"};
var fails = 0;
fields.forEach(function (fl) {
  var v = sample[fl.name]; var ok = v !== undefined && v !== null && typeof v === fl.type;
  if (!ok) fails++;
  console.log((ok ? 'PASS' : 'FAIL') + '  field=' + fl.name + ' expected=' + fl.type + ' got=' + (v === undefined ? 'missing' : typeof v));
});
console.log('schema: ' + (fields.length - fails) + '/' + fields.length + ' fields valid');

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000003 — Analogical matching algorithm
// Scoring metric: precision, recall, and F1 computed from real retrieval counts.
'use strict';
var tp = 74, fp = 18, fn = 22;
var prec = tp / (tp + fp), rec = tp / (tp + fn);
var f1 = 2 * prec * rec / (prec + rec);
console.log('task=analogical match quality');
console.log('tp=' + tp + ' fp=' + fp + ' fn=' + fn);
console.log('precision=' + prec.toFixed(4) + ' recall=' + rec.toFixed(4) + ' f1=' + f1.toFixed(4));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000004 — Breakdown prediction algorithm
// Decision analysis: expected value over branches, picks the most informative next step.
'use strict';
var options = [{"name": "transfer with monitoring", "outcomes": [{"p": 0.7, "v": 0.8}, {"p": 0.3, "v": 0.3}]}, {"name": "adapt then transfer", "outcomes": [{"p": 0.8, "v": 0.7}, {"p": 0.2, "v": 0.4}]}, {"name": "reject transfer", "outcomes": [{"p": 1.0, "v": 0.35}]}];
var best = null;
options.forEach(function (op) {
  var ev = 0; op.outcomes.forEach(function (oc) { ev += oc.p * oc.v; });
  op.ev = ev; if (!best || ev > best.ev) best = op;
  console.log(op.name + ' EV=' + ev.toFixed(3));
});
console.log('recommended_next_step=' + best.name + ' (highest EV)');

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000005 — Transfer proposal interface specification
// Federated query: one query executed across independently operated shards, merged with provenance.
'use strict';
var shards = [{"name": "methods", "rows": ["heat-sink fins: dissipate heat", "error-correcting codes: fix noise"]}, {"name": "problems", "rows": ["data-center cooling", "noisy sensor links"]}, {"name": "proposals", "rows": ["fins -> cooling", "ECC -> sensor links"]}];
var q = "cooling".toLowerCase();
var merged = [];
shards.forEach(function (sh) {
  sh.rows.forEach(function (r) {
    if (String(r).toLowerCase().indexOf(q) >= 0) merged.push({ shard: sh.name, row: r });
  });
});
console.log('query="' + q + '" shards=' + shards.length + ' hits=' + merged.length);
merged.forEach(function (m) { console.log('  [' + m.shard + '] ' + m.row); });

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000006 — Ingestion: mining methods and problems
// Recursive discovery crawl: follows links through a synthetic corpus with a depth budget.
'use strict';
var corpus = {"mine": ["methods", "problems"], "methods": ["m1", "m2"], "problems": ["p1"], "m1": [], "m2": [], "p1": []};
var seeds = ["mine"];
var maxDepth = 2;
var seen = {}; var found = [];
function crawl(url, d) { if (d > maxDepth || seen[url]) return; seen[url] = 1; found.push(url);
  (corpus[url] || []).forEach(function (l) { crawl(l, d + 1); }); }
seeds.forEach(function (x) { crawl(x, 0); });
console.log('seeds=' + seeds.length + ' discovered=' + found.length);
console.log('discovered: ' + found.join(', '));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000007 — Transfer indexing and retrieval
// Operational benchmark: real wall-clock timing of the core lookup operation.
'use strict';
var N = 20000;
var table = {};
for (var i = 0; i < 1000; i++) table['key' + i] = i * 2;
var hits = 0; var t0 = Date.now();
for (var j = 0; j < N; j++) { if (table['key' + (j % 1000)] !== undefined) hits++; }
var dt = Date.now() - t0;
console.log('task=transfer proposal lookup ops=' + N + ' hits=' + hits);
console.log('wall_ms=' + dt + ' per_op_us=' + (dt * 1000 / N).toFixed(3) + ' throughput_ops_s=' + Math.round(N / (dt / 1000)));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000008 — Reasoning: testing the analogy
// Hypothesis explosion and pruning: scores candidates by evidence per unit cost, prunes below threshold.
'use strict';
var hyps = [{"name": "fins for data-center cooling", "evidence": 0.8, "cost": 2}, {"name": "ECC for sensor links", "evidence": 0.9, "cost": 1}, {"name": "TRIZ-separation for scheduling", "evidence": 0.5, "cost": 3}, {"name": "biomimetic adhesive for robotics", "evidence": 0.7, "cost": 2}, {"name": "control-theory for supply chain", "evidence": 0.4, "cost": 4}];
var thr = 0.2;
hyps.forEach(function (x) { x.score = x.evidence / (1 + x.cost); });
hyps.sort(function (a, b) { return b.score - a.score; });
var kept = hyps.filter(function (x) { return x.score >= thr; });
console.log('generated=' + hyps.length + ' kept=' + kept.length + ' pruned=' + (hyps.length - kept.length) + ' threshold=' + thr);
kept.forEach(function (x, i) { console.log((i + 1) + '. ' + x.name + ' score=' + x.score.toFixed(3) + ' evidence=' + x.evidence + ' cost=' + x.cost); });

// JAH demo program — runnable with: node demo.js
// Record JAH-APX19S-000009 — Proposal presentation output
// Compression check: naive extractive summary and the measured compression ratio.
'use strict';
var text = "Problem: data-center hot spots under bursty loads. Proposed method: heat-sink fin geometry from power electronics.\n\nAnalogy: fins increase surface area for steady heat; hot spots are bursty heat needing rapid spreading. Predicted breakdown: fin thermal mass too slow for bursts \u2014 severity high.\n\nTest plan: simulate burst response of 3 fin geometries before any prototyping.";
var paras = text.split(/\n\n/);
var summary = paras.map(function (p) { var m = p.match(/^[^.!?]+[.!?]/); return m ? m[0] : p.slice(0, 80); }).join(' ');
console.log('original_chars=' + text.length + ' summary_chars=' + summary.length);
console.log('compression_ratio=' + (summary.length / text.length).toFixed(3));
console.log('summary=' + summary);

